/* Dedicated inbox story. Fictional people and messages; no operational actions. */
const inboxStory=[
 {step:'01 / A question after closing',title:'The interest is here. The salon is closed.',channel:'Instagram DM · 8:42 pm',message:'Hi! Do you offer a wash and treatment? I’m in Kingston and hoping to come in on Saturday.',reply:'Hi! We offer wash and treatment services. Would you like the service details, or help asking our team about Saturday?',owner:'Configured AI assistant',note:'Answers from approved service information. No invented price or appointment availability.',benefit:'A useful first response can keep the enquiry moving, even outside opening hours.'},
 {step:'02 / One shared source of answers',title:'The answer sounds like your business.',channel:'Instagram DM · Same conversation',message:'Can I book a treatment if I have a sensitive scalp?',reply:'Our stylist should help with that before you book. I’ll flag your question for the team rather than recommend a treatment here.',owner:'Human review requested',note:'An agreed boundary keeps personal advice with a qualified person.',benefit:'Consistent information for routine questions, with room for human judgment when it matters.'},
 {step:'03 / A person takes the lead',title:'Danielle picks up the story, not the pieces.',channel:'Instagram DM · Next opening period',message:'Thanks, I’d like to speak to the stylist first.',reply:'Hi, it’s Danielle. I can see your question above. Let’s talk through what you need before we arrange a visit.',owner:'Danielle · Team owner',note:'The team sees the thread, takes ownership and confirms the next step.',benefit:'Less repeating for the customer. A clearer next action for the team.'}
];
function inboxStoryView(i){const s=inboxStory[i];return `<div class="ib-story-copy"><span class="eyebrow">${s.step}</span><h3>${s.title}</h3><p>${s.benefit}</p><div class="ib-owner"><span aria-hidden="true">↗</span><div><small>VISIBLE RESPONSIBILITY</small><strong>${s.owner}</strong></div></div></div><div class="ib-phone"><div class="ib-phone-top"><b>Danielle’s salon</b><span>${s.channel}</span></div><div class="ib-bubble">${s.message}</div><div class="ib-bubble ib-reply">${s.reply}</div><p class="ib-note">${s.note}</p><div class="ib-channel-return">↩ Reply through the original channel</div></div>`;}
pages.inbox=()=>`<section class="ib-hero"><div class="wrap"><div><a class="breadcrumb" href="#/platform">AyudaGrow / Platform / Unified inbox</a><span class="eyebrow">Many ways to reach you. One place to respond.</span><h1>Keep the conversation.<br><em>Not the chaos.</em></h1><p>WhatsApp here. An Instagram question there. Bring supported conversations into a shared inbox, so your team can see the context, own the reply and keep the customer moving forward.</p><div class="actions"><a class="button" href="#/contact">Let’s connect your conversations <span>→</span></a><button type="button" class="textlink ib-jump" data-inbox-explore>See the inbox ↓</button></div></div><div class="ib-hero-art" aria-label="Illustration: messages connect to the team with shared context"><div class="ib-orbit"><span>Customer asks</span><span>Context stays</span><span>Team responds</span></div><img src="assets/mascot-phone.png" alt="AyudaGrow assistant holding a phone"><div class="ib-art-label"><b>One team. A shared view.</b><small>AI support + human care</small></div></div></div></section>
<div class="ib-benefits wrap"><span>Less app-switching</span><span>More useful context</span><span>A clear owner for the next step</span></div>`+
section(`<div id="ib-explore" class="section-head"><div><span class="eyebrow">Explore the connected inbox</span><h2>The channel changes.<br>The care shouldn’t.</h2></div><p>Select a channel to follow a sample message into the team inbox and see the reply return to where it started.</p></div>${visual('inbox')}<p class="micro visual-disclosure">Illustrative interface based on the supplied Conversations reference, with fictional contacts and messages. This is not a live inbox. Channel eligibility, permissions, response windows and charges vary and are confirmed during setup.</p>`,'inbox-focus')+
section(`<div class="section-head"><div><span class="eyebrow">A familiar evening in Kingston</span><h2>She’s finished for the day.<br>The enquiries haven’t.</h2></div><p>Follow an illustrative salon enquiry from an after-hours question to a thoughtful human reply. Select each moment to see what changes.</p></div><div class="ib-story-controls" role="group" aria-label="Choose a moment in the sample conversation">${['After hours','Approved answers','Human handoff'].map((v,i)=>`<button type="button" data-inbox-step="${i}" aria-pressed="${i===0}" aria-controls="ib-story"><span>0${i+1}</span>${v}</button>`).join('')}</div><div class="ib-story" id="ib-story" aria-live="polite">${inboxStoryView(0)}</div><p class="micro">Danielle and this conversation are fictional. This example describes an agreed workflow, not a client result or a promise of instant human availability.</p>`,'ib-scenario')+
section(`<div class="ib-knowledge"><div><span class="eyebrow">Your business knowledge, put to work</span><h2>Helpful answers start<br>with what you know.</h2><p>Give the assistant the information you want customers to receive: services, opening hours, locations, policies and the questions your team answers every day.</p><p>Agree the tone, test the answers and keep the source information current. When something is missing, uncertain or personal, the next step should be a person, not a guess.</p><a class="textlink" href="#/ai">Explore AI support →</a></div><div class="ib-knowledge-board"><span class="eyebrow">A practical knowledge checklist</span><div><b>01</b><span>What you offer<small>Services, useful details and approved pricing</small></span></div><div><b>02</b><span>How you work<small>Hours, locations and customer policies</small></span></div><div><b>03</b><span>When to ask a person<small>Exceptions, uncertainty and sensitive questions</small></span></div><div><b>04</b><span>How you stay current<small>Named content owner and regular review</small></span></div><p>Approved information → configured answers → team review</p></div></div>`)+
section(`<div class="section-head"><div><span class="eyebrow">Available beyond the front desk</span><h2>After-hours support.<br>Human responsibility.</h2></div><p>AI can be configured to respond around the clock on supported connected channels. That means 24/7 assistance for suitable questions, not a promise that every issue is resolved immediately.</p></div>${cardList([['Keep routine answers consistent','Use the same approved business information across configured AI conversations. Review the answers as your services, policies and opening hours change.'],['Make the handoff intentional','Agree what AI can handle, when it should stop and who receives the conversation. Tell customers what to expect when your people are unavailable.'],['Share the workload clearly','Use the team inbox, assigned conversations and followed conversations to keep responsibility visible. Agree a daily review for enquiries that still need attention.'],['Connect the next useful action','Move from a conversation to a booking request, quotation or follow-up task where configured. Let people confirm availability, commitments and exceptions.']])}<div class="ib-boundary"><b>The setup makes the difference.</b><p>AI behaviour, channel support, operating availability and handoff rules depend on configuration, provider policies and the selected plan. Human support hours are agreed separately. AI responses should be tested and reviewed; they can be incomplete or incorrect.</p></div>`,'how')+
section(`<div class="ib-ready"><div><span class="eyebrow">Start with your real workflow</span><h2>Which conversation<br>gets lost today?</h2><p>Start with the channels your customers use and the questions your team repeats. We’ll help define the connections, approved answers, ownership and human fallback before you switch anything on.</p><a href="#/contact" class="button blue">Talk through your inbox <span>→</span></a></div><ol><li><b>Connect thoughtfully</b><span>Confirm channels, permissions, eligibility and costs.</span></li><li><b>Set the boundaries</b><span>Choose knowledge, response rules and handoff owners.</span></li><li><b>Practise as a team</b><span>Test ordinary questions and exceptions before launch.</span></li></ol></div>`)+
section(`<div class="section-head"><h2>A few useful answers.</h2></div><div class="ib-faq"><details><summary>Will every channel work with my account?</summary><p>Not automatically. The channels shown are examples of the intended journey. AyudaGrow needs to confirm account eligibility, connection method, messaging permissions, response windows and any additional charges for your setup.</p></details><details><summary>Does a shared inbox mean the same customer is always recognised?</summary><p>No. Conversation history depends on the connected channel and how contact records are matched. Agree how your team handles duplicate records and identity checks. Moving between channels does not guarantee one automatically merged history.</p></details><details><summary>Can my team take over from AI?</summary><p>Human handoff is part of the workflow to define and test. Agree the triggers, assignment, notifications and how automated replies pause when a person takes responsibility. Exact controls depend on configuration and available features.</p></details><details><summary>Is everything included in one price?</summary><p>The scope and selected plan determine what is included. Channels, AI usage, messaging, setup and ongoing support may have separate charges. Confirm these before activation.</p></details></div>`)+cta();
const inboxPriorWiring=wireExpanded;
wireExpanded=function(){inboxPriorWiring();document.querySelector("[data-inbox-explore]")?.addEventListener("click",()=>document.getElementById("ib-explore").scrollIntoView({behavior:matchMedia("(prefers-reduced-motion: reduce)").matches?"auto":"smooth"}));document.querySelectorAll('[data-inbox-step]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-inbox-step]').forEach(other=>other.setAttribute('aria-pressed',String(other===button)));document.getElementById('ib-story').innerHTML=inboxStoryView(Number(button.dataset.inboxStep));}));};
render();
